function createLogger(opts: { level: "debug" | "info" | "warn" | "error"; now: () => string; write: (line: string) => void }) {
  const log = (level: string, message: string, fields: Record<string, unknown> = {}) => {
    opts.write(JSON.stringify({
      time: opts.now(),
      level,
      message,
      ...fields
    }));
  };

  return {
    debug: (message: string, fields?: Record<string, unknown>) => log("debug", message, fields),
    info: (message: string, fields?: Record<string, unknown>) => log("info", message, fields),
    warn: (message: string, fields?: Record<string, unknown>) => log("warn", message, fields),
    error: (message: string, fields?: Record<string, unknown>) => log("error", message, fields),
    child: () => log
  };
}

function summarize(lines: string[]) {
  const durations: number[] = [];
  let total = 0;
  let errors = 0;

  for (const line of lines) {
    try {
      const value = JSON.parse(line);
      if (typeof value.status === "number") {
        total++;
        if (value.status >= 500) errors++;
      }
      if (typeof value.durationMs === "number") durations.push(value.durationMs);
    } catch {
      // Ignore invalid JSON.
    }
  }

  return {
    total,
    errors,
    errorRate: total ? errors / total : 0,
    p95: durations.length ? Math.max(...durations) : null
  };
}

exercise.solution:
function createLogger(opts: { level: "debug" | "info" | "warn" | "error"; now: () => string; write: (line: string) => void }) {
  const levels = { debug: 0, info: 1, warn: 2, error: 3 } as const;

  const redact = (value: unknown): unknown => {
    if (Array.isArray(value)) {
      return value.map((item) => redact(item));
    }

    if (value && typeof value === "object") {
      const result: Record<string, unknown> = {};
      for (const [key, item] of Object.entries(value)) {
        if (["password", "token", "authorization", "secret"].includes(key.toLowerCase())) {
          result[key] = "[REDACTED]";
        } else {
          result[key] = redact(item);
        }
      }
      return result;
    }

    return value;
  };

  const create = (context: Record<string, unknown>) => {
    const log = (level: "debug" | "info" | "warn" | "error", message: string, fields: Record<string, unknown> = {}) => {
      if (levels[level] < levels[opts.level]) {
        return;
      }

      const entry = {
        time: opts.now(),
        level,
        message,
        ...fields,
        ...context
      };

      opts.write(JSON.stringify(redact(entry)));
    };

    return {
      debug: (message: string, fields?: Record<string, unknown>) => log("debug", message, fields),
      info: (message: string, fields?: Record<string, unknown>) => log("info", message, fields),
      warn: (message: string, fields?: Record<string, unknown>) => log("warn", message, fields),
      error: (message: string, fields?: Record<string, unknown>) => log("error", message, fields),
      child: (fields: Record<string, unknown> = {}) => create({ ...context, ...fields })
    };
  };

  return create({});
}

function summarize(lines: string[]) {
  const durations: number[] = [];
  let total = 0;
  let errors = 0;

  for (const line of lines) {
    try {
      const value = JSON.parse(line);

      if (typeof value.status === "number") {
        total++;
        if (value.status >= 500) {
          errors++;
        }
      }

      if (typeof value.durationMs === "number") {
        durations.push(value.durationMs);
      }
    } catch {
      // Ignore invalid JSON.
    }
  }

  durations.sort((a, b) => a - b);

  const p95 = durations.length === 0
    ? null
    : durations[Math.ceil(0.95 * durations.length) - 1];

  return {
    total,
    errors,
    errorRate: total === 0 ? 0 : Math.round((errors / total) * 1000) / 1000,
    p95
  };
}

