  write: (line) => lines.push(line)
});
logger.info("Task created", { taskId: "42", status: 201 });
const entry = JSON.parse(lines[0]);
return entry.time === "2026-10-04T10:00:00Z" &&
  entry.level === "info" &&
  entry.message === "Task created" &&
  entry.taskId === "42" &&
  entry.status === 201;

