const result = summarize([
  JSON.stringify({ status: 200, durationMs: 100 }),
  JSON.stringify({ status: 201, durationMs: 200 }),
  JSON.stringify({ status: 404, durationMs: 300 }),
  JSON.stringify({ status: 500, durationMs: 400 }),
  JSON.stringify({ status: 503, durationMs: 500 })
]);
