return result.total === 2 && result.errors === 1 && result.errorRate === 0.5 && result.p95 === 200;

const durations = Array.from({ length: 20 }, (_, index) => index + 1);
const lines = durations.map((durationMs) => JSON.stringify({ status: 200, durationMs }));
const result = summarize(lines);
return result.p95 === 19;

const result = summarize([
  JSON.stringify({ status: 200 }),
  JSON.stringify({ status: 500 }),
  JSON.stringify({ message: "no status" })
]);
const empty = summarize([]);
